<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sistema Solar Interior · Missão Terra–Marte</title>
<style>
  html, body { margin:0; height:100%; overflow:hidden; background:#04060d;
    color:#dfe6f2; font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; }
  #c { position:fixed; inset:0; display:block; }
  .panel { position:fixed; padding:10px 14px; border:1px solid rgba(120,150,200,.25);
