<body>
<canvas id="c"></canvas>

<div class="panel" id="fps">
  FPS (instantâneo): <b><span id="fpsI">–</span></b><br>
  FPS (média): <b><span id="fpsA">–</span></b>
</div>

<div class="panel" id="mission">
  Dia da missão: <b class="day" id="day">0</b> <span class="muted">/ <span id="dayTot">973</span></span><br>
  <span class="phase" id="phase">…</span>
</div>

<div class="panel" id="controls">
  <button id="play">⏸ Pausa</button>
  <label>Velocidade <input type="range" id="speed" min="0" max="100" value="50">
    <span id="spdV" class="muted"></span></label>
  <button id="reset">↺ Reiniciar missão</button>
  <button id="jArr">Chegada a Marte (259)</button>
  <button id="jEnd">Fim da missão (973)</button>
</div>

<div class="panel" id="info"></div>

<script>
(() => {
"use strict";

/* ================= Constantes físicas ================= */
const RAD = Math.PI / 180, DEG = 180 / Math.PI;

const PER = { mer: 87.969, ven: 224.701, ear: 365.256, mar: 686.980 }; // dias
const AUR = { mer: 0.387,  ven: 0.723,   ear: 1.0,     mar: 1.524 };  // UA

/* Missão:
   - A nave sobe 180° numa elipse de Hohmann (periélio 1 UA, afélio 1.524 UA).
   - Partida: a nave sai de 180° (posição da Terra no dia 0, ângulo 0°) e chega
     ao afélio exatamente quando Marte lá estiver  →  ao fim de 259 dias.
   - Assim o ângulo inicial de Marte tem de ser 180° − 360·259/686.98 ≈ 44.28°
     (o ângulo de fase "Marte à frente da Terra" ≈ 44°, como requerido).
   - Regresso: a nave abandona Marte no fim da espera e cobre ~180° em 259 d,
     chegando exatamente à posição real da Terra (o varrimento é ajustado aos
     décimos de grau para o encontro ser exato no dia 973). */
const T_OUT = 259, STAY = 455, T_RET = 259;
const T_STAY_END = T_OUT + STAY;          // 714
const T_TOT = T_OUT + STAY + T_RET;       // 973
const MAR0 = ((180 - 360 * T_OUT / PER.mar) % 360 + 360) % 360; // ≈ 44.2755°
const SWEEP_RET = (ang(0, PER.ear, T_TOT) - ang(MAR0, PER.mar, T_STAY_END) + 360) % 360;

function ang(a0, per, d) { return (a0 + 360 * d / per) % 360; }
const earthAng = d => ang(0, PER.ear, d);
const marsAng  = d => ang(MAR0, PER.mar, d);

function at(r, deg) { const a = deg * RAD; return { x: r * Math.cos(a), y: r * Math.sin(a) }; }
function bodyAt(au, per, a0, d) { return at(au, ang(a0, per, d)); }

/* Posição da nave num dado dia (0..T_TOT definidos; depois da chegada fica com a Terra).
   DETERMINÍSTICA — a mesma função serve a animação e ao contrato de verificação. */
function shipPosition(d) {
  d = Math.max(0, d);
  const a = (AUR.ear + AUR.mar) / 2;                 // 1.262 UA
  const e = (AUR.mar - AUR.ear) / (AUR.mar + AUR.ear);
  if (d <= T_OUT) {                                  // ida: elipse de Hohmann (Kepler, E linear em t)
    const E = Math.PI * d / T_OUT;
    const r = a * (1 - e * Math.cos(E));
    const nu = Math.atan2(Math.sqrt(1 - e * e) * Math.sin(E), Math.cos(E) - e); // 0°..180°
    return at(r, earthAng(0) + nu * DEG);            // chega ao afélio = posição de Marte em 259 d
  }
  if (d <= T_STAY_END) {                             // espera: colada a Marte
    return at(AUR.mar, marsAng(d));
  }
  if (d <= T_TOT) {                                  // regresso: elipse afélio→periélio
    const p = (d - T_STAY_END) / T_RET;
    const r = a * (1 + e * Math.cos(Math.PI * p));
    return at(r, marsAng(T_STAY_END) + SWEEP_RET * p);
  }
  return at(AUR.ear, earthAng(d));                   // missão concluída, com a Terra
}

/* Corpos (para desenho) */
const BODIES = [
  { name:"Mercury", au:AUR.mer, per:PER.mer, a0:205,    color:"#b3a89b", px:3.4 },
  { name:"Venus",   au:AUR.ven, per:PER.ven, a0:245,    color:"#ecc77e", px:6.4 },
  { name:"Earth",   au:AUR.ear, per:PER.ear, a0:0,      color:"#5aa2f2", px:7.0 },
  { name:"Mars",    au:AUR.mar, per:PER.mar, a0:MAR0,   color:"#e2683e", px:4.8 },
];
const BY_NAME = {}; BODIES.forEach(b => BY_NAME[b.name] = b);

/* ================= Contrato de verificação ================= */
let missionDay = 0;
window.__bench = {
  bodies: BODIES.map(b => ({ name: b.name, auRadius: b.au, periodDays: b.per, angleDeg0: b.a0 })),
  mission: {
    departurePhaseAngleDeg: MAR0,   // ≈ 44.28° (Marte à frente da Terra no dia 0)
    outboundDays: T_OUT,            // 259
    stayDays: STAY,                 // 455
    returnDays: T_RET,              // 259
    totalDays: T_TOT                // 973
  },
  setMissionDay(day) {
    const v = Number(day);
    missionDay = isFinite(v) && v > 0 ? v : 0;
  },
  getState() {
    const p = shipPosition(missionDay);
    return { missionDay: missionDay, shipAU: { x: p.x, y: p.y } };
  }
};

/* Trajeto pré-computado (para desenhar a linha do plano e a parte percorrida) */
const TRAIL = [];
for (let d = 0; d <= T_TOT; d++) TRAIL.push(shipPosition(d));

/* ================= Estado da animação ================= */
let playing = true;
let daysPerSec = 25;
const CYCLE = T_TOT + 120; // após a chegada, acompanha a Terra 120 d e reinicia

/* ================= Canvas ================= */
const cv = document.getElementById("c");
const ctx = cv.getContext("2d");
let W = 0, H = 0, S = 100, stars = [];

function mulberry32(s) {
  return function () {
    s |= 0; s = s + 0x6D2B79F5 | 0;
    let t = Math.imul(s ^ s >>> 15, 1 | s);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

function resize() {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth; H = window.innerHeight;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  cv.style.width = W + "px"; cv.style.height = H + "px";
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  S = (Math.min(W, H) / 2 - Math.min(70, Math.min(W, H) * 0.07)) / 1.72;
  const rnd = mulberry32(1234567);
  stars = [];
  const n = Math.round(W * H / 4200);
  for (let i = 0; i < n; i++)
    stars.push([rnd() * W, rnd() * H, 0.3 + rnd() * 1.3, 0.25 + rnd() * 0.65]);
}
window.addEventListener("resize", resize);
resize();

function sx(x) { return W / 2 + x * S; }
function sy(y) { return H / 2 - y * S; }

/* ================= HUD ================= */
const $day = document.getElementById("day");
const $phase = document.getElementById("phase");
const $fpsI = document.getElementById("fpsI");
const $fpsA = document.getElementById("fpsA");
document.getElementById("dayTot").textContent = T_TOT;
document.getElementById("info").innerHTML =
  "Janela de lançamento no dia 0: Marte a <b>" + MAR0.toFixed(2) + "°</b> à frente da Terra<br>" +
  "Ida (Hohmann): <b>" + T_OUT + " d</b> · Espera em Marte: <b>" + STAY + " d</b> · " +
  "Regresso: <b>" + T_RET + " d</b> · <b>Ida+vinda+permanência: " + T_TOT + " d</b><br>" +
  "Períodos: Mercúrio 87.97 d · Vênus 224.7 d · Terra 365.26 d · Marte 686.98 d";

function phaseText(d) {
  if (d <= 0.001) return "Janela de lançamento aberta — a nave parte da Terra";
  if (d < T_OUT) return "Transferência de ida (Hohmann): dia " + d.toFixed(0) + " / " + T_OUT;
  if (d < T_STAY_END) return "Na superfície de Marte — espera: dia " + (d - T_OUT).toFixed(0) + " / " + STAY;
  if (d <= T_TOT + 1e-9) return "Transferência de regresso: dia " + (d - T_STAY_END).toFixed(0) + " / " + T_RET;
  return "Missão concluída — a nave chegou à Terra no dia " + T_TOT;
}

/* ================= Controlos ================= */
const $play = document.getElementById("play");
const $speed = document.getElementById("speed");
const $spdV = document.getElementById("spdV");

function applySpeed() {
  daysPerSec = Math.round(((+$speed.value / 100) ** 2) * 100 * 10) / 10;
  $spdV.textContent = "1 s = " + daysPerSec.toFixed(1) + " dias";
}
$speed.addEventListener("input", applySpeed);
applySpeed();

$play.addEventListener("click", () => {
  playing = !playing;
  $play.textContent = playing ? "⏸ Pausa" : "▶ Retomar";
});
document.getElementById("reset").addEventListener("click", () => { missionDay = 0; });
document.getElementById("jArr").addEventListener("click", () => { missionDay = T_OUT + 0.05; });
document.getElementById("jEnd").addEventListener("click", () => { missionDay = T_TOT + 0.05; });

/* ================= Desenho ================= */
function draw(nowMs) {
  ctx.clearRect(0, 0, W, H);
  const g0 = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, Math.max(W, H) * 0.7);
  g0.addColorStop(0, "#070b18"); g0.addColorStop(1, "#03040a");
  ctx.fillStyle = g0; ctx.fillRect(0, 0, W, H);

  for (const s of stars) { ctx.globalAlpha = s[3]; ctx.fillStyle = "#cfd9ee";
    ctx.fillRect(s[0], s[1], s[2], s[2]); }
  ctx.globalAlpha = 1;

  // órbitas
  ctx.lineWidth = 1;
  for (const b of BODIES) {
    ctx.beginPath();
    ctx.arc(W / 2, H / 2, b.au * S, 0, Math.PI * 2);
    ctx.strokeStyle = "rgba(140,165,215,0.30)";
    ctx.stroke();
  }

  // trajeto planeado da nave
  ctx.beginPath();
  for (let i = 0; i < TRAIL.length; i++) {
    const p = TRAIL[i];
    if (i === 0) ctx.moveTo(sx(p.x), sy(p.y)); else ctx.lineTo(sx(p.x), sy(p.y));
  }
  ctx.setLineDash([5, 5]);
  ctx.strokeStyle = "rgba(255,176,92,0.35)";
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.setLineDash([]);

  // parte já percorrida
  if (missionDay > 0.01) {
    const dEff = Math.min(missionDay, T_TOT);
    const i = Math.floor(dEff);
    const cur = shipPosition(missionDay);
    ctx.beginPath();
    ctx.moveTo(sx(TRAIL[0].x), sy(TRAIL[0].y));
    for (let k = 1; k <= i && k < TRAIL.length; k++) ctx.lineTo(sx(TRAIL[k].x), sy(TRAIL[k].y));
    ctx.lineTo(sx(cur.x), sy(cur.y));
    ctx.strokeStyle = "#ffb35c";
    ctx.lineWidth = 1.8;
    ctx.stroke();
  }

  // Sol
  const sunPx = Math.max(13, S * 0.105);
  let gr = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, sunPx * 2.4);
  gr.addColorStop(0, "rgba(255,235,180,0.95)");
  gr.addColorStop(0.35, "rgba(255,170,60,0.35)");
  gr.addColorStop(1, "rgba(255,140,40,0)");
  ctx.fillStyle = gr;
  ctx.beginPath(); ctx.arc(W / 2, H / 2, sunPx * 2.4, 0, Math.PI * 2); ctx.fill();
  gr = ctx.createRadialGradient(W / 2 - sunPx * 0.3, H / 2 - sunPx * 0.3, sunPx * 0.1, W / 2, H / 2, sunPx);
  gr.addColorStop(0, "#fff3c8"); gr.addColorStop(0.7, "#ffcf5e"); gr.addColorStop(1, "#ff9a33");
  ctx.fillStyle = gr;
  ctx.beginPath(); ctx.arc(W / 2, H / 2, sunPx, 0, Math.PI * 2); ctx.fill();

  // planetas
  ctx.textAlign = "center";
  ctx.font = "11px system-ui, sans-serif";
  for (const b of BODIES) {
    const p = bodyAt(b.au, b.per, b.a0, missionDay);
    const x = sx(p.x), y = sy(p.y);
    gr = ctx.createRadialGradient(x - b.px * 0.4, y - b.px * 0.4, b.px * 0.2, x, y, b.px);
    gr.addColorStop(0, lighten(b.color, 0.35)); gr.addColorStop(1, b.color);
    ctx.fillStyle = gr;
    ctx.beginPath(); ctx.arc(x, y, b.px, 0, Math.PI * 2); ctx.fill();

    ctx.fillStyle = "rgba(230,238,255,0.85)";
    ctx.fillText(b.name, x, y - b.px - 5);

    if (b.name === "Mars" && missionDay > T_OUT - 1e-9 && missionDay <= T_STAY_END + 1e-9) {
      const pulse = 4 + 2 * Math.sin(nowMs / 300);
      ctx.beginPath(); ctx.arc(x, y, b.px + 4 + pulse * 0.4, 0, Math.PI * 2);
      ctx.strokeStyle = "rgba(255,190,120,0.5)"; ctx.lineWidth = 1; ctx.stroke();
    }
  }

  // nave
  const sp = shipPosition(missionDay);
  const x = sx(sp.x), y = sy(sp.y);
  ctx.beginPath(); ctx.arc(x, y, 9, 0, Math.PI * 2);
  const gg = ctx.createRadialGradient(x, y, 0, x, y, 9);
  gg.addColorStop(0, "rgba(255,255,255,0.9)"); gg.addColorStop(1, "rgba(255,200,120,0)");
  ctx.fillStyle = gg; ctx.fill();
  ctx.beginPath(); ctx.arc(x, y, 3.4, 0, Math.PI * 2);
  ctx.fillStyle = "#ffffff"; ctx.fill();
  ctx.fillStyle = "rgba(255,255,255,0.8)";
  ctx.font = "10px system-ui, sans-serif";
  ctx.fillText("nave", x, y + 16);
}

function lighten(hex, k) {
  const n = parseInt(hex.slice(1), 16);
  let R = (n >> 16) & 255, G = (n >> 8) & 255, B = n & 255;
  R = Math.round(R + (255 - R) * k); G = Math.round(G + (255 - G) * k); B = Math.round(B + (255 - B) * k);
  return "rgb(" + R + "," + G + "," + B + ")";
}

/* ================= Bucle de animação + FPS ================= */
const CYCLE = T_TOT + 120;
let last = performance.now();
let startT = last;
let frames = 0;
let fpsI = 0;

function frame(now) {
  const dt = (now - last) / 1000;
  last = now;
  if (dt > 0 && dt < 1) fpsI = fpsI ? fpsI * 0.9 + (1 / dt) * 0.1 : 1 / dt;

  if (playing) {
    missionDay += Math.min(dt, 0.25) * daysPerSec;
    if (missionDay >= CYCLE) missionDay -= CYCLE;
  }

  draw(now);
  frames++;
  const inst = now - startT;
  const fpsA = inst > 0 ? frames / (inst / 1000) : 0;
  $fpsI.textContent = fpsI.toFixed(1);
  $fpsA.textContent = fpsA.toFixed(1);
  $day.textContent = missionDay.toFixed(1);
  $phase.textContent = phaseText(missionDay);

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

})();
</script>
</body>
</html>
"}

